      const packFallbackFilter = !applyPreviewFilter && pack.media?.defaultFilter && pack.media.defaultFilter !== "none" ? pack.media.defaultFilter : !applyPreviewFilter && pack.patch?.imageFilter?.enabled ? pack.patch.imageFilter.preset : "none";
      const mediaFilter = applyPreviewFilter ? filterState.preset : packFallbackFilter;
